<?php
namespace App\Http\Controllers; use App\Models\{Credential,Project}; use App\Services\VaultCrypto; use App\Services\AuditService; use Illuminate\Http\Request;
class CredentialController extends Controller { public function index(){return view('credentials.index',['credentials'=>Credential::with('project')->latest()->get(),'projects'=>Project::orderBy('name')->get()]);} public function create(){return view('credentials.form',['credential'=>new Credential,'projects'=>Project::orderBy('name')->get()]);} public function store(Request $r,VaultCrypto $c){$d=$r->validate(['project_id'=>'nullable|exists:projects,id','label'=>'required|max:150','username'=>'nullable|max:255','password'=>'required','url'=>'nullable|max:2048','category'=>'nullable|max:100','notes'=>'nullable']);$k=$c->sessionKey();$x=Credential::create(['project_id'=>$d['project_id']??null,'label'=>$d['label'],'username_enc'=>$c->encrypt($d['username']??'',$k),'password_enc'=>$c->encrypt($d['password'],$k),'url'=>$d['url']??null,'category'=>$d['category']??null,'notes_enc'=>$c->encrypt($d['notes']??'',$k),'password_changed_at'=>now()]);AuditService::log('CREDENTIAL_CREATED',$d['label'],$x??null);return redirect()->route('credentials.index')->with('ok','Credencial cifrada y guardada.');} public function edit(Credential $credential,VaultCrypto $c){$k=$c->sessionKey();return view('credentials.form',['credential'=>$credential,'projects'=>Project::orderBy('name')->get(),'plainUser'=>$c->decrypt($credential->username_enc,$k),'plainNotes'=>$c->decrypt($credential->notes_enc,$k)]);} public function update(Request $r,Credential $credential,VaultCrypto $c){$d=$r->validate(['project_id'=>'nullable|exists:projects,id','label'=>'required|max:150','username'=>'nullable|max:255','password'=>'nullable','url'=>'nullable|max:2048','category'=>'nullable|max:100','notes'=>'nullable']);$k=$c->sessionKey();$x=['project_id'=>$d['project_id']??null,'label'=>$d['label'],'username_enc'=>$c->encrypt($d['username']??'',$k),'url'=>$d['url']??null,'category'=>$d['category']??null,'notes_enc'=>$c->encrypt($d['notes']??'',$k),'password_changed_at'=>now()];if(!empty($d['password'])){$x['password_enc']=$c->encrypt($d['password'],$k);$x['password_changed_at']=now();}$credential->update($x);AuditService::log('CREDENTIAL_UPDATED',$credential->label,$credential);return redirect()->route('credentials.index')->with('ok','Credencial actualizada.');} public function destroy(Credential $credential){$label=$credential->label;$credential->delete();AuditService::log('CREDENTIAL_DELETED',$label);return redirect()->route('credentials.index')->with('ok','Credencial eliminada.');} public function toggleFavorite(Credential $credential){$credential->update(['favorite'=>!$credential->favorite]);AuditService::log('CREDENTIAL_FAVORITE_TOGGLED',$credential->label,$credential);return back()->with('ok',$credential->favorite?'Marcada como favorita.':'Quitada de favoritos.');} public function reveal(Credential $credential,VaultCrypto $c){AuditService::log('CREDENTIAL_REVEALED',$credential->label,$credential);$credential->forceFill(['last_revealed_at'=>now()])->saveQuietly();$k=$c->sessionKey();return response()->json(['username'=>$c->decrypt($credential->username_enc,$k),'password'=>$c->decrypt($credential->password_enc,$k)]);} }
